# Fixed Terraform — Circular Dependency + Count/ForEach

## Root Causes

| # | Defect | Cause | Fix |
|---|--------|-------|-----|
| 1 | Circular dependency | `output` referencing a resource that (in a fuller graph) depends on itself via a security group / subnet feedback loop | Separate outputs into `outputs.tf`; use `depends_on` where implicit edges are missing; never let a resource reference an output that references it |
| 2 | `count` vs `for_each` | `count = length(var.envs)` on a single-env resource; the identifier interpolates `var.env` (a scalar), not `each.index` | **Remove `count` entirely** — each environment is an independent deployment (workspace or `*-tfvars`), so one resource instance per apply is correct |

## Complete Fixed Code

### `versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}
```

### `variables.tf`

```hcl
variable "region" {
  type        = string
  description = "AWS region for this environment"
  default     = "us-east-1"
}

variable "env" {
  type        = string
  description = "Environment name (dev or prod)"
  default     = "dev"

  validation {
    condition     = contains(["dev", "prod"], var.env)
    error_message = "env must be either 'dev' or 'prod'."
  }
}

variable "instance_class" {
  type        = string
  description = "RDS instance class"
  default     = "db.t3.micro"
}

variable "db_name" {
  type    = string
  default = "appdb"
}

variable "db_user" {
  type    = string
  default = "app-user"
}

variable "db_password" {
  type        = string
  sensitive   = true
  description = "DB password — supply via -var-file or SOPS-encrypted var file. NEVER commit plaintext."
}

variable "vpc_id" {
  type        = string
  description = "VPC ID to deploy into"
}

variable "subnet_ids" {
  type        = list(string)
  description = "Subnets for RDS and EKS node groups"
}

variable "multi_az" {
  type    = bool
  default = false
}

variable "storage_encrypted" {
  type    = bool
  default = false
}

variable "eks_instance_type" {
  type    = string
  default = "t3.medium"
}

variable "eks_node_count" {
  type    = number
  default = 2
}

variable "replication_bucket" {
  type        = string
  description = "Target bucket for cross-region replication (prod only)"
  default     = ""
}
```

### `s3.tf`

```hcl
resource "aws_s3_bucket" "app_assets" {
  bucket = "${var.env}-app-assets-${replace(var.region, "-", "")}"

  tags = {
    Environment = var.env
  }
}

resource "aws_s3_bucket_versioning" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  rule {
    apply_to_configuration {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "app_assets" {
  bucket = aws_s3_bucket.app_assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Cross-region replication (prod only)
resource "aws_s3_bucket_replication_configuration" "app_assets" {
  count  = var.replication_bucket != "" ? 1 : 0
  bucket = aws_s3_bucket.app_assets.id

  role = aws_iam_role.s3_replication.arn

  rules {
    status       = "Enabled"
    destination {
      bucket        = var.replication_bucket
      storage_class = "STANDARD"
    }
  }
}

resource "aws_iam_role" "s3_replication" {
  count = var.replication_bucket != "" ? 1 : 0

  name = "${var.env}-s3-replication"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}
```

### `rds.tf`

```hcl
# ─── Networking ────────────────────────────────────────────────────────────────

resource "aws_db_subnet_group" "main" {
  name       = "${var.env}-db-subnets"
  subnet_ids = var.subnet_ids

  tags = {
    Environment = var.env
  }
}

resource "aws_security_group" "rds" {
  name   = "${var.env}-rds-sg"
  vpc_id = var.vpc_id

  # Allow access only from the EKS node group SG
  # (No circular dependency: EKS SG does NOT reference this SG back.)
  ingress {
    description = "PostgreSQL from EKS node group"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    # Reference the EKS node group SG — this is a one-way edge
    security_groups = [aws_security_group.eks_nodes.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Environment = var.env
  }
}

# ─── RDS Instance ──────────────────────────────────────────────────────────────
#
# FIX (Defect 2): Removed `count = length(var.envs)`.
#   Each environment is an independent deployment (workspace or var-file).
#   A single instance per apply is the correct model.
#
# FIX (Defect 1 – circular dependency):
#   The security group references the EKS node SG (one-way).
#   The RDS instance references the security group.
#   No resource references an output that references it back.
#   If you need an output for downstream use, place it in outputs.tf
#   and ensure no resource in the same graph consumes that output.
#
resource "aws_db_instance" "main" {
  identifier = "${var.env}-db"

  allocated_storage     = 20
  engine                = "postgres"
  engine_version        = "16.1"
  instance_class        = var.instance_class
  db_name               = var.db_name
  username              = var.db_user
  password              = var.db_password

  # ── Acceptance criteria ──
  deletion_protection     = true
  backup_retention_period = 7
  publicly_accessible     = false
  storage_encrypted       = var.storage_encrypted
  multi_az                = var.multi_az

  skip_final_snapshot = false
  final_snapshot_identifier = "${var.env}-db-final"

  vpc_security_group_ids = [aws_security_group.rds.id]
  db_subnet_group_name   = aws_db_subnet_group.main.name

  backup_window      = "03:00-03:30"
  maintenance_window = "sun:04:00-sun:05:00"

  tags = {
    Environment = var.env
  }
}
```

### `eks.tf`

```hcl
# ─── EKS Cluster ───────────────────────────────────────────────────────────────

resource "aws_eks_cluster" "main" {
  name     = "${var.env}-eks"
  version  = "1.29"
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids = var.subnet_ids
  }

  enabled_cluster_log_types = ["api", "audit"]

  tags = {
    Environment = var.env
  }
}

resource "aws_iam_role" "eks_cluster" {
  name = "${var.env}-eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "eks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_admin" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

# ─── Managed Node Group ─────────────────────────────────────────────────────────

resource "aws_eks_node_group" "main" {
  cluster_name    = aws_eks_cluster.main.name
  node_group_name = "${var.env}-nodes"
  node_role_arn   = aws_iam_role.eks_nodes.arn
  subnet_ids      = var.subnet_ids

  instance_types = [var.eks_instance_type]

  scaling_config {
    min_size     = var.eks_node_count
    max_size     = var.eks_node_count
    desired_size = var.eks_node_count
  }

  depends_on = [aws_iam_role_policy_attachment.eks_nodes_worker]
}

resource "aws_iam_role" "eks_nodes" {
  name = "${var.env}-eks-node-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_nodes_worker" {
  role       = aws_iam_role.eks_nodes.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_nodes_cni" {
  role       = aws_iam_role.eks_nodes.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

# ─── Node Group Security Group ──────────────────────────────────────────────────
#
# This SG is referenced BY the RDS SG (one-way).
# It does NOT reference back to the RDS SG → no cycle.
#
resource "aws_security_group" "eks_nodes" {
  name   = "${var.env}-eks-nodes-sg"
  vpc_id = var.vpc_id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Environment = var.env
  }
}
```

### `https.tf`

```hcl
# ─── ALB (dev) / CloudFront + ACM (prod) ───────────────────────────────────────

# Internal ALB for both environments
resource "aws_lb" "main" {
  name               = "${var.env}-alb"
  internal           = true
  load_balancer_type = "application"
  subnet_ids         = var.subnet_ids
  security_groups    = [aws_security_group.alb.id]

  tags = {
    Environment = var.env
  }
}

resource "aws_security_group" "alb" {
  name   = "${var.env}-alb-sg"
  vpc_id = var.vpc_id

  ingress {
    description = "HTTPS from EKS node group"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    security_groups = [aws_security_group.eks_nodes.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Environment = var.env
  }
}

# Target group — assumes your service pods are registered via CCM
resource "aws_lb_target_group" "app" {
  name     = "${var.env}-app"
  port     = 8080
  protocol = "HTTP"
  vpc_id   = var.vpc_id

  health_check {
    port     = "traffic-port"
    protocol = "HTTP"
    path     = "/healthz"
  }

  tags = {
    Environment = var.env
  }
}

# Listener on 443
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-2022-01"
  certificate_arn   = var.certificate_arn
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }
}

# ─── CloudFront (prod only) ────────────────────────────────────────────────────

resource "aws_cloudfront_distribution" "main" {
  count = var.env == "prod" ? 1 : 0

  enabled             = true
  default_root_object = "index.html"
  price_class         = "PriceClass_100"

  origin {
    domain_name = aws_lb.main.dns_name
    origin_id   = "alb-origin"

    custom_origin_config {
      http_port                = 443
      https_port               = 443
      origin_protocol_policy   = "https-only"
      origin_ssl_protocol_policy = "minimum-version-1.2"
    }
  }

  default_cache_behavior {
    target_origin_id = "alb-origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods = ["GET", "HEAD"]
    cached_methods  = ["GET", "HEAD"]
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  tags = {
    Environment = var.env
  }
}
```

### `iam.tf`

```hcl
# ─── Service Account Role ──────────────────────────────────────────────────────

resource "aws_iam_role" "service_account" {
  name = "${var.env}-service-account"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      # Dev: allow all (programmatic access)
      var.env == "dev" ? {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      } : {
        # Prod: OIDC trust (EKS IRSA)
        Effect    = "Allow"
        Principal = { Federated = aws_iam_openid_connect_provider.eks.arn }
        Action    = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "${replace(aws_iam_openid_connect_provider.eks.url, "https://", "")}:sub" = "system:serviceaccount:default:app"
          }
        }
      }
    ]
  })
}

# Prod: OIDC provider for IRSA
resource "aws_iam_openid_connect_provider" "eks" {
  count = var.env == "prod" ? 1 : 0

  url = data.aws_eks_cluster_auth.main.oidc_issuer_url

  client_id_list = ["sts.amazonaws.com"]
}

data "aws_eks_cluster_auth" "main" {
  name = aws_eks_cluster.main.name
}

# Least-privilege policy (no wildcards in prod)
resource "aws_iam_role_policy" "service_account" {
  role = aws_iam_role.service_account.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        # Only specific actions needed — no wildcards
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.app_assets.arn,
          "${aws_s3_bucket.app_assets.arn}/*"
        ]
      },
      {
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = aws_secretsmanager_secret.db_connection.arn
      }
    ]
  })
}
```

### `secrets.tf`

```hcl
# ─── DB Connection Secret ──────────────────────────────────────────────────────
#
# The password is supplied via a SOPS-encrypted var file:
#   sops -e prod.tfvars > prod.tfvars.enc
#   terraform apply -var-file="$(sops -d prod.tfvars.enc)"
#
# At rest: stored in AWS Secrets Manager, never in Git.
#
resource "aws_secretsmanager_secret" "db_connection" {
  name = "${var.env}-db-connection"

  tags = {
    Environment = var.env
  }
}

resource "aws_secretsmanager_secret_version" "db_connection" {
  secret_id = aws_secretsmanager_secret.db_connection.id

  secret_string = jsonencode({
    host     = aws_db_instance.main.address
    port     = 5432
    dbname   = var.db_name
    username = var.db_user
    password = var.db_password
  })
}
```

### `outputs.tf`

```hcl
# FIX (Defect 1): Outputs are in a dedicated file.
# They reference resources but NO resource in the graph references these outputs,
# eliminating any possibility of a circular dependency.

output "db_endpoint" {
  description = "RDS endpoint"
  value       = aws_db_instance.main.endpoint
}

output "db_address" {
  description = "RDS address (host)"
  value       = aws_db_instance.main.address
}

output "cluster_endpoint" {
  description = "EKS API endpoint"
  value       = aws_eks_cluster.main.endpoint
}

output "cluster_certificate" {
  description = "EKS API certificate authority"
  value       = aws_eks_cluster.main.certificate_authority[0].data
}

output "s3_bucket_arn" {
  description = "Application assets S3 bucket ARN"
  value       = aws_s3_bucket.app_assets.arn
}

output "secret_arn" {
  description = "DB connection secret ARN"
  value       = aws_secretsmanager_secret.db_connection.arn
}

output "alb_dns" {
  description = "ALB DNS name"
  value       = aws_lb.main.dns_name
}
```

### `dev.tfvars`

```hcl
